files.referenceContent:
ARRIVALS = [
    {"name": "Ada", "minute": 2},
    {"name": "Grace", "minute": 9},
    {"name": "Alan", "minute": 5},
    {"name": "Katherine", "minute": 17},
    {"name": "Linus", "minute": 0},
]


def late_arrivals(arrivals):
    """Return the names of everyone whose minute is greater than 5, in order."""
    return [arrival["name"] for arrival in arrivals if arrival["minute"] > 5]


def main():
    for name in late_arrivals(ARRIVALS):
        print(name)


if __name__ == "__main__":
    main()
